// /calls/list answers once per batch; the rest of the workflow is per call.
// Drive holds duplicate copies of the same call ("name (1).wav"): identity is
// the Asterisk uniqueid, the Drive file is just storage. Keep one copy per
// uniqueid (largest file wins) so a duplicate never costs a second ASR+judge.
const { recordings = [] } = $input.first().json;
const best = new Map();
for (const r of recordings) {
  const prev = best.get(r.external_id);
  if (!prev || (r.size_bytes || 0) > (prev.size_bytes || 0)) best.set(r.external_id, r);
}
return [...best.values()].map(r => ({ json: r }));

// One place where the /evaluate request body is assembled, and the only node
// the HTTP call reads from. Before this existed the body was built out of five
// separate cross-node references ($('Cohere Arabic ASR') four times plus
// $json), so a single dropped field still produced a request that SUCCEEDED --
// which is exactly how the follow-up history went missing without anything
// failing.
//
// It also removes every reference to the ASR node from the evaluation path, so
// a judge retry (which never runs ASR) cannot reach a node that did not run.
const claim = $('Claim work').item.json;
const tr    = $('Load stored transcript').item.json;

// Postgres hands numeric and smallint back as STRINGS. An un-coerced value here
// reaches the model as "0.82" instead of 0.82 and quietly changes the metadata
// block the judge reads.
const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));

const history = $input.item.json.followup_history || 'unavailable';

return {
  json: {
    interaction_id:   tr.interaction_id,
    uniqueid:         claim.uniqueid,
    claim_token:      claim.claim_token,
    work_stage:       claim.work_stage,
    meta:             claim.meta,
    asr_confidence:   num(tr.asr_confidence),
    followup_history: history,
    request: {
      conversation: tr.dialogue,
      input_type: 'call_transcript',
      metadata: {
        asr_confidence:   num(tr.asr_confidence),
        diarization:      tr.diarization,
        duration_seconds: num(tr.duration_seconds),
        channels:         num(tr.channels),
      },
      followup_history: history,
      run_pass1: true,
      run_pass2: true,
    },
  },
};
